/* Explore's catalogue read by one index (round AU). Production logged "[ExplorePage] Products error: products took longer than 20s" and "[CategoryPage] Products error: TimeoutError". Both pages read the newest hundred products that are published, not physical and not a community tier (status = 'published' AND type <> 'physical' AND community_id IS NULL, ORDER BY created_at DESC LIMIT 100). The index on (status, created_at) finds the published ones in order but then reads every newer physical product and community tier row from the table and throws it away, so a store that imported a few thousand physical products put that many row reads in front of every Explore load. Two partial indexes, nothing else: `products_explore_catalogue_idx` on products (created_at DESC) where exactly those three hold, so the read is the hundred entries it returns; and `products_creator_page_idx` on products (creator_id, created_at DESC) where published, for a creator page's grid and its count of published products. A missing table or column is skipped with a notice. No row changes. LOCKS: a plain CREATE INDEX stops writes to products while it builds, held until the paste ends, so on a large products table run supabase/sql/RUN_EXPLORE_INDEXES_CONCURRENTLY.sql first, one line per Run, or with psql -f; this part then finds each index made and takes no lock. Until it runs Explore reads the same rows, more slowly. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 451: products_explore_catalogue_idx skipped, public.products does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'type') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'community_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'created_at') THEN RAISE NOTICE 'part 451: products_explore_catalogue_idx skipped, public.products lacks a column it needs (community_id comes with part 81)'; RETURN; END IF; IF to_regclass('public.products_explore_catalogue_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS products_explore_catalogue_idx ON public.products (created_at DESC) WHERE status = 'published' AND type <> 'physical' AND community_id IS NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 451: products_creator_page_idx skipped, public.products does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'status') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'creator_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'created_at') THEN RAISE NOTICE 'part 451: products_creator_page_idx skipped, public.products lacks a column it needs'; RETURN; END IF; IF to_regclass('public.products_creator_page_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS products_creator_page_idx ON public.products (creator_id, created_at DESC) WHERE status = 'published'; END $do$;
notify pgrst, 'reload schema';
